package pl.zagranietyper.service;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import pl.zagranietyper.model.*;import pl.zagranietyper.repository.FootballFixturePlayerStatisticsRepository;import java.time.Instant;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class FootballFixturePlayerStatisticsInfrastructureTest {@Test void knownZeroRemainsDistinctFromAbsentAndAppearanceIsPositiveOnly(){var m=new ObjectMapper();var zero=player(m,1,0,0);var absent=player(m,2,null,null);assertEquals(0,zero.shotsTotal());assertNull(absent.shotsTotal());assertFalse(zero.appearanceConfirmed());assertFalse(absent.appearanceConfirmed());assertTrue(player(m,3,1,0).appearanceConfirmed());}@Test void completeSnapshotSurvivesFailedRefresh(){assertFalse(FootballFixturePlayerStatisticsRepository.shouldReplace(FootballFixturePlayerStatisticsSnapshot.FetchStatus.COMPLETE,FootballFixturePlayerStatisticsSnapshot.FetchStatus.FETCH_FAILED));assertTrue(FootballFixturePlayerStatisticsRepository.shouldReplace(FootballFixturePlayerStatisticsSnapshot.FetchStatus.COMPLETE,FootballFixturePlayerStatisticsSnapshot.FetchStatus.COMPLETE));}@Test void sharedResolverIsConservativeAndRejectsAmbiguity(){var r=new FootballEventPlayerResolver();var one=List.of(new FootballEventPlayerResolver.PlayerIdentity(1L,"Łukasz Kowalski"),new FootballEventPlayerResolver.PlayerIdentity(2L,"Jan Nowak"));assertEquals(1,r.resolveIdentities("L. Kowalski",one).playerId());var two=List.of(new FootballEventPlayerResolver.PlayerIdentity(1L,"Jan Kowalski"),new FootballEventPlayerResolver.PlayerIdentity(2L,"Adam Kowalski"));assertEquals(FootballEventPlayerResolver.Status.AMBIGUOUS,r.resolveIdentities("Kowalski",two).status());assertEquals(FootballEventPlayerResolver.Status.UNRESOLVED,r.resolveIdentities("Kowalsky",two).status());}private static FootballFixturePlayerStatisticsSnapshot.Player player(ObjectMapper m,long id,Integer minutes,Integer shots){return new FootballFixturePlayerStatisticsSnapshot.Player(10L,"T",id,"P"+id,minutes,null,null,null,null,null,shots,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,m.createObjectNode(),m.createObjectNode());}}
